package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Canonical key identifying a household by its owner's last name and address. Two owners
 * belong to the same household when their keys are equal: last name and address are compared
 * case-insensitively with leading/trailing and repeated whitespace collapsed to a single
 * space, so incidental formatting differences do not hide a match.
 */
final class HouseholdKey {

    private HouseholdKey() {
    }

    static String of(String lastName, String address) {
        return normalize(lastName) + '�' + normalize(address);
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

